def readiness(checks):
    if not checks:
        return {"percent": 100, "missing": []}
    done = sum(1 for ok in checks.values() if ok)
    return {"percent": round(done / len(checks) * 100), "missing": sorted(name for name, ok in checks.items() if not ok)}

